-- Sample data for local development (H2). Lives in its own Flyway location so it is
-- never applied in production. IDs are generated by the database; rows are linked
-- through natural keys so the script is safe on any database.
-- Every sample user has the password: Password@123

-- ---------------------------------------------------------------- permissions

-- ---------------------------------------------------------------------- roles

-- ---------------------------------------------------------------------- groups

-- ---------------------------------------------------------------------- users

-- ----------------------------------------------------- role -> permissions
SELECT r.id, p.id FROM roles r CROSS JOIN permissions p WHERE r.name = 'ADMIN';

SELECT r.id, p.id FROM roles r JOIN permissions p
  ON p.name IN ('USER_READ', 'USER_CREATE', 'USER_UPDATE', 'USER_DELETE', 'GROUP_READ')
WHERE r.name = 'USER_MANAGER';

SELECT r.id, p.id FROM roles r JOIN permissions p
  ON p.name IN ('USER_READ', 'USER_UPDATE')
WHERE r.name = 'SUPPORT';

SELECT r.id, p.id FROM roles r JOIN permissions p
  ON p.name IN ('USER_READ', 'GROUP_READ', 'ROLE_READ', 'PERMISSION_READ', 'REPORT_VIEW', 'AUDIT_VIEW')
WHERE r.name = 'AUDITOR';

SELECT r.id, p.id FROM roles r JOIN permissions p
  ON p.name IN ('USER_READ', 'GROUP_READ')
WHERE r.name = 'VIEWER';

-- ---------------------------------------------------------- group -> roles
SELECT g.id, r.id FROM user_groups g JOIN roles r ON r.name = 'ADMIN'   WHERE g.name = 'Administrators';
SELECT g.id, r.id FROM user_groups g JOIN roles r ON r.name = 'VIEWER'  WHERE g.name = 'Engineering';
SELECT g.id, r.id FROM user_groups g JOIN roles r ON r.name = 'SUPPORT' WHERE g.name = 'Support Team';
SELECT g.id, r.id FROM user_groups g JOIN roles r ON r.name = 'AUDITOR' WHERE g.name = 'Finance';

-- ------------------------------------------------------ user -> direct roles
SELECT u.id, r.id FROM users u JOIN roles r ON r.name = 'ADMIN'        WHERE u.username = 'admin';
SELECT u.id, r.id FROM users u JOIN roles r ON r.name = 'VIEWER'       WHERE u.username = 'alice';
SELECT u.id, r.id FROM users u JOIN roles r ON r.name = 'AUDITOR'      WHERE u.username = 'carol';
SELECT u.id, r.id FROM users u JOIN roles r ON r.name = 'USER_MANAGER' WHERE u.username = 'erin';

-- ----------------------------------------------------- group memberships
SELECT g.id, u.id FROM user_groups g JOIN users u ON u.username = 'admin' WHERE g.name = 'Administrators';
SELECT g.id, u.id FROM user_groups g JOIN users u ON u.username IN ('alice', 'erin') WHERE g.name = 'Engineering';
SELECT g.id, u.id FROM user_groups g JOIN users u ON u.username IN ('bob', 'dave', 'erin') WHERE g.name = 'Support Team';
SELECT g.id, u.id FROM user_groups g JOIN users u ON u.username = 'carol' WHERE g.name = 'Finance';
